<script setup>
import {watch,onUnmounted} from 'vue'
import PrototypeChart from './PrototypeChart.vue'
import {createObservations,observationLabels,observationChart} from './useInvestmentObservations.js'
const props=defineProps({runId:String,report:Object,developer:Boolean})
const ctl=createObservations(),{view,summary,error,busy,candidate}=ctl
watch(()=>props.runId,id=>ctl.load(id),{immediate:true});onUnmounted(ctl.dispose)
const route=id=>({TREND_SWING:'趋势波段',QUALITY_GROWTH:'质量成长',UNASSIGNED:'尚未适配'})[id]||id
const pct=v=>v==null?'尚无到期样本':(Number(v)*100).toFixed(1)+'%'
const profileLabel=id=>({NO_PROFILE:'未填资金',SYNTHETIC:'测试画像',SMALL:'十万元以下',MEDIUM:'十万至百万元',LARGE:'百万元以上'})[id]||id
const localTime=v=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
const direction=sid=>props.report.research_opinions.find(o=>o.security_id===sid)?.direction==='FAVORABLE'?'看多':'看空'
</script>
<template><section class="panel rep-section forward-view"><div class="section-heading"><h2>后续跟踪与复盘</h2><button v-if="view?.status==='ENROLLED'" class="btn" :disabled="busy" @click="ctl.observe(runId)">{{ busy?'正在取得真实行情…':'核对最新真实行情' }}</button></div>
<p v-if="error" role="alert" class="error-text">{{ error }}</p><p v-if="!view&&!error" role="status">正在读取原判断与观察记录…</p><p v-if="view?.status==='NOT_ENROLLED'" class="condition-note">{{ view.message }}</p>
<template v-if="view?.status==='ENROLLED'"><p class="condition-note">原判断已封存。未来 {{ view.protocol.horizon_sessions }} 个交易日后核对方向；条件触发单独观察，不代表已经成交。</p>
<p v-if="view.incomplete_acquisitions" role="status" class="condition-note">有 {{ view.incomplete_acquisitions }} 次取数尚未留下完整结果，已取得资料保留。若当前没有正在取数，可再次点击核对。</p>
<p v-if="view.last_attempt?.status==='ACQUISITION_FAILED'" role="alert" class="error-text">本次取数未完成：{{ view.last_attempt.error }}。原判断与以往记录保留，可再次核对。</p>
<p v-if="!view.latest">尚未取得后续观察。点击“核对最新真实行情”保存本次核查；尚未到期时显示等待。</p>
<template v-if="view.latest"><p class="condition-note">最近核查 {{ localTime(view.latest.created_at) }}（北京时间） · 核查日期范围截至 {{ view.latest.evaluation.through }}</p><div class="forward-grid"><article v-for="s in view.latest.evaluation.stocks" :key="s.security_id"><div class="section-heading"><strong>{{ s.name }} · 原判断{{ direction(s.security_id) }}</strong><span class="tag">{{ observationLabels[s.status]||s.status }}</span></div><p>{{ s.observed_sessions }} / {{ s.horizon_sessions }} 个交易日 · 到期日 {{ s.target_date||'日历待补全' }}</p><progress :value="s.observed_sessions" :max="s.horizon_sessions" :aria-label="s.name+'观察进度'"></progress><p v-if="s.status==='MATURED'"><strong>实际{{ {UP:'上涨',DOWN:'下跌',FLAT:'平盘'}[s.actual_direction] }} · {{ s.correct?'方向符合':'方向未符合' }}</strong> · 复权价格变化 {{ pct(s.price_return) }}</p><PrototypeChart v-if="s.points.length" :block="observationChart(s,report)" :height="170"/><p>原路线条件首次满足：{{ s.first_trigger.FROZEN_SELECTED_ROUTE||'尚未观察到' }}<span v-if="s.signals.some(p=>p.status!=='OBSERVED')"> · 部分窗口或停牌无法核对，不能视为始终未触发</span></p><p v-if="s.signals.some(p=>p.risk_reference_breached)">已观察到收盘触及原风险参考，须重新评估原判断。</p><details><summary>原反证与失效条件</summary><p v-for="c in s.counterarguments" :key="c.claim_id">{{ c.text }} <span class="muted">· 需新增证据复核</span></p><p v-for="c in s.invalidation" :key="c.text">{{ c.text }} <span class="muted">· 文字条件未自动判定</span></p></details></article></div><p class="condition-note">这里只核对方向和收盘条件，不表示已成交或已验证收益。经营与政策反证需要另取新证据。</p></template>
<details v-if="summary"><summary>方向成绩与简单基线 · {{ summary.registered_samples }} 个登记样本</summary><p class="condition-note">同一股票可有重叠期限，这些样本并非相互独立。仅完整到期样本进入方向评分，未到期、失败、缺失与停牌分别保留。这里不展示收益优势。</p><div class="stats-scroll"><table><thead><tr><th>路线 / 画像 / 期限</th><th>登记 / 到期</th><th>方向准确率</th><th>始终看涨</th><th>始终看跌</th><th>前期方向延续</th></tr></thead><tbody><tr v-for="g in summary.groups" :key="g.route_id+g.profile_group+g.horizon_sessions"><td>{{ route(g.route_id) }} / {{ profileLabel(g.profile_group) }} / {{ g.horizon_sessions }}日</td><td>{{ g.registered }} / {{ g.matured }}</td><td>{{ pct(g.accuracy) }}</td><td>{{ pct(g.baseline_accuracy.ALWAYS_UP) }}</td><td>{{ pct(g.baseline_accuracy.ALWAYS_DOWN) }}</td><td>{{ pct(g.baseline_accuracy.PAST_20_SESSION_SIGN) }}</td></tr></tbody></table></div><p v-for="g in summary.groups" :key="'state'+g.route_id+g.profile_group+g.horizon_sessions" class="condition-note">{{ route(g.route_id) }}：{{ Object.entries(g.status_counts).map(([k,v])=>(observationLabels[k]||k)+' '+v).join('，') }}</p></details>
<details v-if="developer"><summary>开发者：冻结协议、路线条件对照与知识候选</summary><p>无方法价格条件、固定趋势路线、原选定路线仅比较条件是否触发。K6这里只记录条件对照；封存材料的模型对照在K7交付页单独查看，两者均不证明知识增益；没有模拟交易收益。 <a href="?developer=1#/delivery">查看K7验收</a></p><p v-for="text in view.latest?.evaluation.limitations||[]" :key="text" class="condition-note">{{ text }}</p><pre v-if="summary">{{ summary }}</pre><pre>{{ view.protocol }}</pre><pre>{{ view.history }}</pre><button class="btn" :disabled="busy||!view.latest" @click="ctl.suggest(runId)">保存为待审核复盘候选</button><p v-if="candidate" role="status">已保存待审核候选 {{ candidate.supplement_id }}，当前状态 {{ candidate.status }}；尚未发布到知识库。</p></details></template>
</section></template>
<style scoped>.forward-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.forward-grid article{border:1px solid var(--border);padding:12px;border-radius:4px;font-size:12px}.forward-grid p{margin:8px 0}.forward-grid progress{width:100%;height:6px;accent-color:var(--accent)}.forward-grid .section-heading{align-items:start;flex-wrap:wrap;gap:8px}summary{cursor:pointer;line-height:1.8}summary:focus-visible{outline:2px solid var(--accent)}details{margin-top:12px}.stats-scroll{overflow:auto}table{width:100%;font-size:12px;text-align:left;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid var(--border);white-space:nowrap}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;font-size:11px}@media(max-width:750px){.forward-grid{grid-template-columns:1fr}.forward-view>.section-heading{flex-wrap:wrap;gap:10px}}</style>
